// Só contas Google (platform vem do cadastro: 'google_ads', 'google', etc)
// A aba da planilha tem o MESMO nome do account_id (ex: "721-845-9036"),
// incluindo os traços - não precisa de sheet_tab_name pra isso.
const accounts = $('Get Ad Accounts').first().json.data || [];
const config = $('Config').first().json;

return accounts
  .filter(a => (a.platform || '').startsWith('google'))
  .map(a => ({
    json: {
      ...a,
      app_url: config.app_url,
      spreadsheet_id: config.spreadsheet_id,
    }
  }));

// Uma linha por campanha por dia - pegamos só as linhas de ontem (D-1),
// mesma regra usada no sync direto (as plataformas só consolidam o dia
// inteiro algumas horas depois da meia-noite).
const account = $('Loop Contas').item.json;
const yesterday = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

const rows = $input.all().map(i => i.json).filter(r => r && !r.error);

const rowsYesterday = rows.filter(r => (r['Day'] || '').toString().trim() === yesterday);

return [{
  json: {
    account,
    yesterday,
    rows: rowsYesterday,
  }
}];

const data = $input.first().json;
const account = data.account;

// Uma campanha por nome distinto encontrado nas linhas de ontem.
const seen = new Set();
const campaigns = [];
for (const row of data.rows) {
  const name = (row['Campaign Name'] || '').toString().trim();
  if (!name || seen.has(name)) continue;
  seen.add(name);
  campaigns.push({
    external_id: name,
    name: name,
    status: 'active',
    raw_data: row,
  });
}

return [{
  json: {
    client_ad_account_id: account.id,
    platform: 'google',
    campaigns,
  }
}];

const data = $('Filtra Linha de Ontem (D-1)').first().json;
const account = data.account;

function toNumber(v) {
  if (v === null || v === undefined || v === '') return 0;
  // planilha em pt-BR usa vírgula decimal (ex: "7,88")
  const n = parseFloat(String(v).replace(/\./g, '').replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

const snapshots = data.rows.map(row => {
  const name = (row['Campaign Name'] || '').toString().trim();
  return {
    entity_level: 'campaign',
    entity_id: name,
    entity_name: name,
    spend: toNumber(row['Cost (Spend)']),
    // Sem coluna de receita real na planilha - ver Sticky "Sobre a planilha".
    revenue: 0,
    impressions: Math.round(toNumber(row['Impressions'])),
    clicks: Math.round(toNumber(row['Clicks'])),
    conversions: Math.round(toNumber(row['Conversions'])),
    reach: 0,
    raw_data: row,
  };
}).filter(s => s.entity_id);

return [{
  json: {
    client_ad_account_id: account.id,
    platform: 'google',
    snapshot_date: data.yesterday,
    snapshots,
  }
}];
